def seed_official_calendar():
    from app.calendar_data import official_rows

    calendar = sa.table(
        "calendar_days",
        sa.column("day", sa.Date), sa.column("kind", sa.String), sa.column("title", sa.String),
        sa.column("source", sa.String),
    )
    bind = op.get_bind()
    existing = {row[0] for row in bind.execute(sa.select(calendar.c.day))}
    rows = [row for row in official_rows() if row["day"] not in existing]
    if rows:
        op.bulk_insert(calendar, rows)


